export type BrandRenderMode = "tile" | "mark";

interface BrandEntry {
	Icon: FC<SVGProps<SVGSVGElement>>;
	/**
	 * "tile" — the icon ships its own brand-colored background; render full-bleed.
	 * "mark" — transparent mark; center it on a neutral chip, tinted by colorClass.
	 */
	mode: BrandRenderMode;
	colorClass?: string;
	/** Share of the chip a "mark" fills; defaults to 0.6. Wordmarks need more. */
	scale?: number;
}

const BRANDS: Record<string, BrandEntry> = {
	chatgpt: { Icon: OpenAIIcon, mode: "tile" },
	claude: { Icon: AnthropicIcon, mode: "tile" },
	gemini: { Icon: GoogleStudioAIIconStatic, mode: "mark" },
	perplexity: {
		Icon: PerplexityIcon,
		mode: "mark",
		colorClass: "text-[#20808d]",
	},
	poe: { Icon: PoeIcon, mode: "mark", colorClass: "text-[#5d5cde]" },
	"t3-chat": { Icon: T3ChatIcon, mode: "mark", colorClass: "text-[#e0117f]" },
	openrouter: {
		Icon: OpenRouterIcon,
		mode: "mark",
		colorClass: "text-foreground",
	},
	"chatgpt-voice": { Icon: OpenAIIcon, mode: "tile" },
	fal: { Icon: FalIcon, mode: "mark", colorClass: "text-foreground" },
	elevenlabs: {
		Icon: ElevenLabsIcon,
		mode: "mark",
		colorClass: "text-foreground",
	},
	higgsfield: {
		Icon: HiggsfieldIcon,
		mode: "mark",
		colorClass: "text-foreground",
	},
	midjourney: {
		Icon: MidjourneyIcon,
		mode: "mark",
		colorClass: "text-foreground",
	},
	krea: { Icon: KreaIcon, mode: "mark", colorClass: "text-foreground" },
	"hugging-face": {
		Icon: HuggingFaceIcon,
		mode: "mark",
		colorClass: "text-[#ff9d00]",
	},
	"kaggle-game-arena": {
		Icon: KaggleIcon,
		mode: "mark",
		colorClass: "text-[#20beff]",
		scale: 0.85,
	},
};

export function getBrand(slug: string): BrandEntry | undefined {
	return BRANDS[slug];
}
